-- Drivers belong to a company; agency links are optional organisational preferences.
INSERT INTO Role(id,code,name,scope,createdAt,updatedAt) VALUES(UUID(),'company_courier','Livreur entreprise','COMPANY',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE code=VALUES(code);
INSERT INTO RolePermission(id,roleId,permissionId,createdAt,updatedAt) SELECT UUID(), target.id,rp.permissionId,NOW(3),NOW(3) FROM Role source JOIN RolePermission rp ON rp.roleId=source.id JOIN Role target ON target.code='company_courier' AND target.scope='COMPANY' WHERE source.code='courier' AND source.scope='AGENCY' ON DUPLICATE KEY UPDATE roleId=VALUES(roleId);
UPDATE CompanyMembership m JOIN Role old ON old.id=m.roleId JOIN Role target ON target.code='company_courier' AND target.scope='COMPANY' SET m.roleId=target.id,m.version=m.version+1,m.updatedAt=NOW(3) WHERE m.organizationRole='courier' AND old.code='company_member' AND m.roleScope='COMPANY';
ALTER TABLE `Delivery` DROP FOREIGN KEY `Delivery_companyId_agencyId_courierId_fkey`, ADD CONSTRAINT `Delivery_company_courier_fk` FOREIGN KEY (companyId,courierId) REFERENCES CompanyMembership(companyId,userId) ON DELETE RESTRICT ON UPDATE RESTRICT;
